class DataProcessor:
    def __init__(self):
        self.data = []

    def load(self, filename):
        f = open(filename, 'r')
        self.data = f.readlines()
        f.close()

    def process(self):
        result = []
        for line in self.data:
            parts = line.split(',')
            if len(parts) == 3:
                result.append({'name': parts[0], 'age': int(parts[1]), 'city': parts[2]})
        return result

    def save(self, filename):
        f = open(filename, 'w')
        for item in self.process():
            f.write(f"{item['name']},{item['age']},{item['city']}\n")
        f.close()
